sys_variable_value.value:
(function execute(inputs, outputs) {
    gs.info('@@@Script loaded');

    var TABLE = 'x_snc_ai_upgrade_0_action_log';
    var UPGRADE_FIELD = 'update_name';

    // Script step input: records_json.
    // Map this variable to the action input containing the JSON text.
    var records = inputs.records_json;

    gs.info('@@@Initial input type: ' + typeof records);

    if (typeof records === 'undefined' || records === null) {
        throw new Error(
            'records_json is missing. Check the Script step input mapping.'
        );
    }

    try {
        // Handle normal JSON and one additional encoding layer.
        for (var pass = 0; pass < 2; pass++) {
            if (typeof records !== 'string') {
                break;
            }

            records = JSON.parse(records.trim());

            gs.info(
                '@@@After parse ' + (pass + 1) +
                ': type=' + typeof records +
                ', isArray=' + Array.isArray(records)
            );
        }
    } catch (e) {
        throw new Error(
            'records_json contains invalid JSON: ' +
            String(e.message || e)
        );
    }

    if (!Array.isArray(records)) {
        throw new Error(
            'records_json must resolve to an array of objects. ' +
            'Received type: ' + typeof records +
            '; object type: ' + Object.prototype.toString.call(records)
        );
    }

    // Validate all fields used for querying and updating.
    var tableCheck = new GlideRecord(TABLE);
    var fields = [
        'file_name',
        UPGRADE_FIELD,
        'action_taken',
        'action_reason'
    ];

    for (var f = 0; f < fields.length; f++) {
        if (!tableCheck.isValidField(fields[f])) {
            throw new Error('Missing or invalid table field: ' + fields[f]);
        }
    }

    var results = [];

    for (var i = 0; i < records.length; i++) {
        var item = records[i];

        var result = {
            index: item && typeof item.index !== 'undefined'
                ? item.index
                : i,
            file_name: item ? item.file_name : null,
            upgrade_id: item ? item.upgrade_id : null
        };

        // Require identifying fields and string action values.
        if (!item ||
            typeof item !== 'object' ||
            Array.isArray(item) ||
            typeof item.file_name !== 'string' ||
            !item.file_name.trim() ||
            typeof item.upgrade_id !== 'string' ||
            !item.upgrade_id.trim() ||
            typeof item.action_taken !== 'string' ||
            typeof item.action_reason !== 'string') {

            result.status = 'invalid_input';
            result.message =
                'Provide an object with non-empty file_name and upgrade_id, ' +
                'and string action_taken and action_reason values.';

            results.push(result);
            continue;
        }

        try {
            var gr = new GlideRecord(TABLE);
            gr.addQuery('file_name', item.file_name);
            gr.addQuery(UPGRADE_FIELD, item.upgrade_id);
            gr.addQuery('action_taken', '');

            // Two matches are sufficient to detect an ambiguous lookup.
            gr.setLimit(2);
            gr.query();

            var matchCount = gr.getRowCount();

            if (matchCount === 0) {
                result.status = 'not_found';
                result.message =
                    'No record matched file_name, upgrade ID, ' +
                    'and an empty action_taken.';
            } else if (matchCount > 1) {
                result.status = 'ambiguous_match';
                result.message =
                    'Multiple records match; none were updated.';
            } else if (gr.next()) {
                gr.setValue('action_taken', item.action_taken);
                gr.setValue('action_reason', item.action_reason);

                var updatedId = gr.update();

                result.status = updatedId ? 'updated' : 'update_failed';

                if (updatedId) {
                    result.sys_id = String(updatedId);
                }
            }
        } catch (e) {
            result.status = 'error';
            result.message = String(e.message || e);
        }

        results.push(result);
    }

    outputs.results_json = JSON.stringify(results);

})(inputs, outputs);

